import React, { useEffect, useState } from 'react';
import { ZimmCountryLanguageMismatch } from 'app/components/ui-kits/organisms/zimmCountryLanguageMismatch';
import { getRegionPrefCookie, setRegionPrefCookie } from 'app/utils/regionPrefCookie';
import { shouldShowLanguagePrompt } from 'app/utils/shouldShowLanguagePrompt';
import { crossSiteUrl } from 'app/utils/crossSiteUrl';
import type { BuildCrossSiteUrl } from 'app/utils/crossSiteUrl';

/**
 * Matches the real shape `useMultiSite()` returns (see
 * `node_modules/@salesforce/retail-react-app/app/hooks/use-multi-site.js`) — declared locally
 * rather than imported, the same technique `useCountryConfig.ts`'s own local `MultiSiteContext`
 * type already uses, since `useMultiSite` itself ships untyped.
 */
export type ZimmLanguagePromptProps = {
  /** The runtime's current PWA site, exactly as `_app` already has it from `useMultiSite()`. */
  site: { id: string; sfccSiteId?: string };
  /** The runtime's current locale, exactly as `_app` already has it from `useMultiSite()`. */
  locale: { id: string };
  /** The real `buildUrl` from `useMultiSite()`, forwarded straight through to `crossSiteUrl`. */
  buildUrl: BuildCrossSiteUrl;
};

type EuLanguageConfigEntry = {
  /** The target PWA site's URL alias — see `config/sites.overlay.js`. */
  readonly alias: string;
  /** The target PWA site's own locale id — see `config/sites.overlay.js`. */
  readonly locale: string;
  /** Phrase-carrying value for the `{inCountry}` copy token (decisions.md's "phrase-carrying
   *  tokens, not bare nouns" note) — always includes its own preposition. */
  readonly countryPhrase: string;
  /** Phrase-carrying value for the `{inLanguage}`/`{inCurrentLanguage}` copy tokens. */
  readonly languagePhrase: string;
};

/**
 * Deliberate, temporary stand-in for real geo-detection (SFCC-817/823) — a fixed language code ->
 * target-site/display map. Approved by Marcel after a live Storybook review of all four cases
 * (see `zimmCountryLanguageMismatch/index.stories.tsx`'s `LanguageDetected*` stories, hand-typed
 * to match this map's real output so a drift between the two shows up as a visible story
 * regression, not a silent divergence).
 *
 * `en` reads "in Ireland", not "the UK": Zimmermann already has a separate, real UK storefront
 * (`ZimmermannUK`, `/uk/`) that this EU-English site is NOT, so naming the UK here would
 * contradict the site's own architecture, not just be geographically approximate — see this exact
 * reasoning recorded in `zimmCountryLanguageMismatch/index.stories.tsx`'s `LanguageDetectedEnglish`
 * story comment, which this map's `en` entry was built to match.
 *
 * `alias`/`locale` verified against `config/sites.overlay.js:39-42`; `countryPhrase`/
 * `languagePhrase` have no config source — they're this feature's own copy. Kept as one combined
 * map (not two that could drift apart) — see this file's own test for the guard that its keys
 * stay identical to `shouldShowLanguagePrompt.ts`'s `SUPPORTED_EU_LANGUAGES`.
 */
export const EU_LANGUAGE_CONFIG: Record<string, EuLanguageConfigEntry> = {
  en: { alias: 'en-eu', locale: 'en-GB', countryPhrase: 'in Ireland', languagePhrase: 'in English' },
  fr: { alias: 'fr-eu', locale: 'fr', countryPhrase: 'in France', languagePhrase: 'in French' },
  it: { alias: 'it-eu', locale: 'it', countryPhrase: 'in Italy', languagePhrase: 'in Italian' },
  es: { alias: 'es-eu', locale: 'es', countryPhrase: 'in Spain', languagePhrase: 'in Spanish' },
};

type LanguagePromptState = {
  isOpen: boolean;
  targetLanguage: string;
};

const CLOSED_STATE: LanguagePromptState = { isOpen: false, targetLanguage: '' };

/**
 * Writes the language-prompt suppression timestamp into the shared `zimm-region-pref` cookie,
 * spreading the existing value first — `regionPrefCookie.ts`'s `setRegionPrefCookie` replaces the
 * whole cookie value (there is no partial-update form), so skipping the spread would silently
 * erase a sibling flag. Confirmed by grep as of this step: `countrySuppressedAt` (the future
 * country-mismatch prompt's own flag, `regionPrefCookie.ts:55`) has no production caller
 * anywhere in this codebase yet — only its type/parse/serialise plumbing exists — so this spread
 * is the only thing standing between a future SFCC-823 write and this container silently
 * clobbering it.
 */
const suppressLanguagePrompt = (): void => {
  setRegionPrefCookie({ ...getRegionPrefCookie(), languageSuppressedAt: Math.floor(Date.now() / 1000) });
};

/**
 * Organism (container) — mounts the EU-domestic language-mismatch prompt (SFCC-689) in `_app`.
 * On mount only, reads `navigator.languages` and the suppression cookie, asks
 * `shouldShowLanguagePrompt` whether to show, and if so renders `ZimmCountryLanguageMismatch`
 * (`variant="language"`); otherwise renders nothing.
 *
 * **Takes `site`/`locale`/`buildUrl` as props, not its own `useMultiSite()` call.**
 * `components.md`'s container/presentational rule allows only `useIntl`/`useUiCopy` as hook
 * exceptions inside `components/` — every other data-fetching hook belongs in a page or another
 * container. `_app` already destructures all three from `useMultiSite()` for its own use, so
 * threading them through as props here keeps this container prop-driven and keeps the `_app`
 * mount to a single JSX line.
 *
 * **Cookie write, then hard navigation — always in that order, always synchronous.**
 * `window.location.href =` unloads the page; a write issued after navigation starts (or an async
 * write) may never land, and the shopper would see the prompt again next visit despite having
 * just acted on it. This is also why switching site is a hard navigation rather than a
 * client-side route change: an EU-domestic site switch changes the Commerce API `siteId`, basket
 * context and locale, all resolved from the URL at boot — a route change would update the address
 * bar and leave the app running against the old site's API.
 */
export const ZimmLanguagePrompt = ({ site, locale, buildUrl }: ZimmLanguagePromptProps) => {
  const [languagePromptState, setLanguagePromptState] = useState<LanguagePromptState>(CLOSED_STATE);

  // Runs once per mount: browser language and the suppression cookie are both read exactly once.
  // Nothing here needs to react to a later site/locale prop change within the same page life — an
  // EU-domestic site switch is always the hard navigation described above, never an in-place
  // update this effect would need to respond to.
  useEffect(() => {
    const result = shouldShowLanguagePrompt({
      sfccSiteId: site.sfccSiteId,
      currentLanguage: locale.id,
      browserLanguages: navigator.languages,
      suppressedAt: getRegionPrefCookie().languageSuppressedAt,
      now: Math.floor(Date.now() / 1000),
    });

    if (result.show) {
      setLanguagePromptState({ isOpen: true, targetLanguage: result.targetLanguage });
    }
  }, []);

  const handleDismiss = (): void => {
    suppressLanguagePrompt();
    setLanguagePromptState(CLOSED_STATE);
  };

  const handleSwitchLanguage = (target: unknown): void => {
    if (typeof target !== 'string') return;
    const config = EU_LANGUAGE_CONFIG[target];
    if (!config) return;

    // Cookie write first, then navigate — both synchronous, no await between them. See this
    // component's own doc comment for why the ordering is load-bearing, not stylistic.
    suppressLanguagePrompt();
    window.location.href = crossSiteUrl(config.alias, config.locale, buildUrl);
  };

  if (!languagePromptState.isOpen) {
    return null;
  }

  const targetConfig = EU_LANGUAGE_CONFIG[languagePromptState.targetLanguage];
  if (!targetConfig) {
    return null;
  }
  const currentConfig = Object.values(EU_LANGUAGE_CONFIG).find((entry) => entry.locale === locale.id);

  return (
    <ZimmCountryLanguageMismatch
      variant="language"
      isOpen={languagePromptState.isOpen}
      onDismiss={handleDismiss}
      inCountry={targetConfig.countryPhrase}
      inLanguage={targetConfig.languagePhrase}
      inCurrentLanguage={currentConfig?.languagePhrase ?? ''}
      target={languagePromptState.targetLanguage}
      onSwitchLanguage={handleSwitchLanguage}
    />
  );
};

export default ZimmLanguagePrompt;
```

6. Run the test command a third time after restoring — paste full output — confirm it is GREEN again (all 9 tests pass), matching step 2's result exactly.
7. Run `git status --porcelain` and confirm ONLY the original 4 entries are dirty (this file being untracked means it'll still show as `?? .../zimmLanguagePrompt/` — that's expected and fine; the concern is whether its CONTENT matches the original, which you should double check with `git diff --no-index /dev/null overrides/app/components/ui-kits/organisms/zimmLanguagePrompt/index.tsx | wc -l` or simply re-reading the file and confirming it's 164 lines ending in `export default ZimmLanguagePrompt;`).

TASK B — React logic correctness (read-only investigation, no further edits needed):

1. The component's `useEffect(() => {...}, [])` (empty dependency array) reads `site.sfccSiteId` and `locale.id` on mount only. Its own doc comment claims this is safe because "an EU-domestic site switch is always the hard navigation described above, never an in-place update this effect would need to respond to." Stress-test this claim: grep the codebase (`overrides/app/`) for other places that change site/locale — search for things like a locale/country switcher, `useMultiSite`, `buildUrl(`, any component with "LocaleSelector"/"CountrySelector"/"SiteSwitcher" in its name, and check `overrides/app/components/_app/index.tsx` itself for how `site`/`locale` get to this component (are they derived fresh on every render from a hook that could return new values without a full page reload, e.g. via client-side routing on a locale-prefixed URL?). Report with file:line evidence: is there ANY existing mechanism in this app that changes `site`/`locale` without a full page navigation? If yes, that would make the empty-deps assumption wrong (stale closure risk). If no, say so plainly with what you searched.
2. Check `handleDismiss`/`handleSwitchLanguage` for stale-closure or functional-updater issues: `setLanguagePromptState(CLOSED_STATE)` is a plain value overwrite, not `setLanguagePromptState(prev => ...)`. Is there any scenario in this component where a functional updater would have been necessary instead (i.e., where the new state depends on the previous state) and using a fixed value instead is a bug? Give your own reasoned verdict, not just a description.
3. Check what happens under React 18 `StrictMode` double-invoking effects in dev (mount → cleanup → mount again): would `shouldShowLanguagePrompt` firing twice on mount cause any observable double-open or duplicate cookie write? Reason through it (there's no cleanup function on this effect at all) and report your conclusion.
4. Write your verdict on whether the empty dependency array is CONFIRMED safe, or a PLAUSIBLE latent bug, with your evidence either way.

Report full raw command output for Task A (not paraphrased), and your reasoned findings for Task B with file:line citations. If restoring the file fails or you're not fully confident it's byte-identical to the original afterward, say so explicitly and show the actual current content rather than asserting success.

