18	import logger from '@salesforce/retail-react-app/app/utils/logger-instance';
19	
20	// Chakra
21	import { SkipNavContent, SkipNavLink } from '@chakra-ui/skip-nav';
22	import {
23	  Box,
24	  Center,
25	  Fade,
26	  Spinner,
27	  useDisclosure,
28	  useStyleConfig,
29	} from '@salesforce/retail-react-app/app/components/shared/ui';
30	// Imported directly from @chakra-ui/react, not the shared/ui barrel: that barrel's
31	// useBreakpointValue re-export is an untyped .jsx passthrough — same reasoning as
32	// product-detail/index.tsx's own import of this hook.
33	import { useBreakpointValue } from '@chakra-ui/react';
34	
35	// Contexts
36	import { CurrencyProvider } from '@salesforce/retail-react-app/app/contexts';
37	
38	// Local Project Components
39	// SFCC-863 — Header/Footer/DrawerMenu/ListMenu/HideOnDesktop/HideOnMobile are all already
40	// overridden; imported via relative paths rather than the base SFCC path per
41	// overrideStyling.md's "importing an already-overridden component" rule. This is not just a
42	// Storybook/Vitest concern here: the ccExtensibility resolver only redirects a base-path
43	// import when the importing file's issuer path is outside overrides/ (see
44	// OverridesResolverPlugin.isFromExtends — it deliberately excludes overrides/ issuers to
45	// avoid circular resolution), and this file lives inside overrides/ itself. A base-path
46	// import from here resolves straight to the raw, un-overridden SFCC module in the real
47	// build too, not just tests — confirmed against `responsive`, whose override changes the
48	// actual mobile/desktop breakpoint (md/768px vs base's lg/992px).
49	import AboveHeader from '@salesforce/retail-react-app/app/components/_app/partials/above-header';
50	import { DrawerMenu } from '../drawer-menu';
51	import Footer from '../footer';
52	import Header from '../header';
53	import Island from '@salesforce/retail-react-app/app/components/island';
54	import { ListMenu, ListMenuContent } from '../list-menu';
55	import { ZimmLanguagePrompt } from '../ui-kits/organisms/zimmLanguagePrompt';
56	import OfflineBanner from '@salesforce/retail-react-app/app/components/offline-banner';
57	import OfflineBoundary from '@salesforce/retail-react-app/app/components/offline-boundary';
58	import { HideOnDesktop, HideOnMobile, MOBILE_DESKTOP_SPLIT } from '../responsive';
59	import ScrollToTop from '@salesforce/retail-react-app/app/components/scroll-to-top';
60	import { StoreLocatorModal } from '@salesforce/retail-react-app/app/components/store-locator';
61	import CheckoutFooter from '@salesforce/retail-react-app/app/pages/checkout/partials/checkout-footer';
62	import CheckoutHeader from '@salesforce/retail-react-app/app/pages/checkout/partials/checkout-header';
63	
64	// Hooks
65	import { AddToCartModalProvider } from '@salesforce/retail-react-app/app/hooks/use-add-to-cart-modal';
66	import { AuthModal, useAuthModal } from '@salesforce/retail-react-app/app/hooks/use-auth-modal';
67	import { BonusProductSelectionModalProvider } from '@salesforce/retail-react-app/app/hooks/use-bonus-product-selection-modal';
68	import { useCurrentBasket } from '@salesforce/retail-react-app/app/hooks/use-current-basket';
69	import { useCurrentCustomer } from '@salesforce/retail-react-app/app/hooks/use-current-customer';
70	import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
71	import { useStoreLocatorModal } from '@salesforce/retail-react-app/app/hooks/use-store-locator';
72	import { useUpdateShopperContext } from '@salesforce/retail-react-app/app/hooks/use-update-shopper-context';
73	
74	// HOCs
75	import { withCommerceSdkReact } from '@salesforce/retail-react-app/app/components/with-commerce-sdk-react/with-commerce-sdk-react';
76	
77	import { PageDesignerProvider } from '@salesforce/commerce-sdk-react/page-designer';
78	import PageDesignerInit from '@salesforce/retail-react-app/app/components/page-designer-init';
79	
80	// Localization
81	import { IntlProvider } from 'react-intl';
82	
83	// Others
84	import {
85	  CAT_MENU_DEFAULT_NAV_SSR_DEPTH,
86	  CAT_MENU_DEFAULT_ROOT_CATEGORY,
87	  DEFAULT_LOCALE,
88	  DEFAULT_SITE_TITLE,
89	  HOME_HREF,
90	  STORE_LOCATOR_IS_ENABLED,
91	  THEME_COLOR,
92	} from '@salesforce/retail-react-app/app/constants';
93	import { fetchTranslations, getTargetLocale } from '@salesforce/retail-react-app/app/utils/locale';
94	import { flatten, isServer, watchOnlineStatus } from '@salesforce/retail-react-app/app/utils/utils';
95	
96	import Seo from '@salesforce/retail-react-app/app/components/seo';
97	import ShopperAgent from '@salesforce/retail-react-app/app/components/shopper-agent';
98	import { initializeRegistry } from '@salesforce/retail-react-app/app/page-designer/registry';
99	
100	// Initialize registry synchronously at module load time so components are available during SSR
101	initializeRegistry();
102	import { getCommerceAgentConfig } from '@salesforce/retail-react-app/app/utils/config-utils';
103	import { getPathWithLocale } from '@salesforce/retail-react-app/app/utils/url';
104	import { useShopperAgent } from '@salesforce/retail-react-app/app/hooks/use-shopper-agent';
105	
106	type AppProps = {
107	  children: React.ReactNode;
108	};
109	
110	type CategoryNode = {
111	  id: string;
112	  categories?: Record<string, CategoryNode>;
113	  [key: string]: unknown;
114	};
115	
116	const PlaceholderComponent = (): React.ReactElement => (
117	  <Center p="2">
118	    <Spinner size="lg" />
119	  </Center>
120	);
121	
122	const DrawerMenuItemWithData = withCommerceSdkReact(
123	  // any: withCommerceSdkReact's injected item-component props aren't typed upstream;
124	  // narrowing here would require re-deriving withCommerceSdkReact's own generic shape,
125	  // out of scope for a copy-first port.
126	  ({ itemComponent: ItemComponent, data, ...rest }: any) => (
127	    <Fade in={true}>
128	      <ItemComponent {...rest} item={data} itemComponent={DrawerMenuItemWithData} />
129	    </Fade>
130	  ),
131	  {
132	    hook: useCategory,
133	    queryOptions: ({ item }: { item: { id: string } }) => ({
134	      parameters: {
135	        id: item.id,
136	      },
137	    }),
138	    placeholder: PlaceholderComponent,
139	  },
140	);
141	
142	const ListMenuContentWithData = withCommerceSdkReact(
143	  // any: same as DrawerMenuItemWithData above.
144	  ({ data, ...rest }: any) => (
145	    <Fade in={true}>
146	      <ListMenuContent {...rest} item={data} />
147	    </Fade>
148	  ),
149	  {
150	    hook: useCategory,
151	    queryOptions: ({ item }: { item: { id: string } }) => ({
152	      parameters: {
153	        id: item.id,
154	        levels: 2,
155	      },
156	    }),
157	    placeholder: PlaceholderComponent,
158	  },
159	);
