38	import {
39	  DEFAULT_DNT_STATE,
40	  STORE_LOCATOR_RADIUS,
41	  STORE_LOCATOR_RADIUS_UNIT,
42	  STORE_LOCATOR_DEFAULT_COUNTRY,
43	  STORE_LOCATOR_DEFAULT_COUNTRY_CODE,
44	  STORE_LOCATOR_DEFAULT_POSTAL_CODE,
45	  STORE_LOCATOR_DEFAULT_PAGE_SIZE,
46	  STORE_LOCATOR_SUPPORTED_COUNTRIES,
47	} from '@salesforce/retail-react-app/app/constants';
48	import { ContentfulLivePreviewProvider } from '@contentful/live-preview/react';
49	
50	// Loaded via React.lazy(), gated to development below, so the devtools chunk is registered but
51	// never fetched in production — @tanstack/react-query-devtools's own top-level `require` of its
52	// devtools implementation isn't NODE_ENV-gated, so a static import would still ship that code to
53	// every shopper even though the exported component renders null outside development (SFCC-860,
54	// flagged by Lighthouse's unused-javascript audit).
55	const ReactQueryDevtools = lazy(() =>
56	  import('@tanstack/react-query-devtools').then((module) => ({ default: module.ReactQueryDevtools })),
57	);
58	
59	// Contentful's image CDN — used by every Contentful-driven page (home, experience) for hero/PLP
60	// imagery. Preconnecting here (rather than per-page) guarantees the hint is in the very first
61	// server-rendered <head>, which is when the browser can actually act on it (SFCC-860, Lighthouse's
62	// uses-rel-preconnect audit). No crossOrigin attribute — Contentful images are always rendered as
63	// plain <img src> with no crossOrigin prop, so the request is always same-mode (anonymous).
64	const CONTENTFUL_IMAGE_CDN_ORIGIN = 'https://images.ctfassets.net';
65	
66	const sfdcUserAgent = generateSfdcUserAgent();
67	
68	// SFCC-856 — name of the meta tag that carries the request's CSP nonce from
69	// the server-rendered HTML into the client bundle. AppConfig runs on both
70	// server and client (see `isServerSide` below); server-side it reads the
71	// nonce straight off `locals.cspNonce`, but the client's `AppConfig.restore`
72	// pass (ssr/browser/main.jsx) starts from a fresh, empty `locals` object with
73	// no request context at all — so the client has no other way to learn this
74	// response's nonce. This meta tag is the handoff between the two.
